const express = require('express');
const { getManager } = require('typeorm');

const app = express();

app.delete('/api/files/:fileId', async (req, res) => {
  const { fileId } = req.params;
  const entityManager = getManager();

  // Scope raw SQL DELETE to the authenticated user's ownership
  try {
    const result = await entityManager.query(
      'DELETE FROM uploaded_documents WHERE id = $1 AND owner_id = $2 RETURNING id, storage_key',
      [fileId, req.user.id]
    );

    if (result.length === 0) {
      return res.status(404).json({ error: 'Document not found or access denied' });
    }

    return res.json({ message: 'Document permanently deleted', fileId });
  } catch (err) {
    return res.status(500).json({ error: 'Delete query execution failed' });
  }
});

module.exports = app;
